/// Percent-encodes SVG markup into a `data:` URI that is safe inside `url("...")`.
pub(super) fn svg_data_uri(svg: &str) -> String {
    let mut out = String::from("data:image/svg+xml,");
    for b in svg.bytes() {
        if b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~') {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

pub(super) fn default_devtools_icons() -> BTreeMap<String, String> {
    DEVTOOLS_DEFAULT_ICONS
        .iter()
        .map(|(name, svg)| (name.to_string(), svg_data_uri(svg)))
        .collect()
}

/// Icon sets come from our own sidebar, but they end up inside a stylesheet evaluated in the
/// DevTools frontend, so only well-formed names and SVG data URIs without quotes are accepted.
pub(super) fn clean_icons(raw: HashMap<String, String>) -> BTreeMap<String, String> {
    raw.into_iter()
        .filter(|(name, uri)| {
            !name.is_empty()
                && name.len() <= 40
                && name
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
                && uri.starts_with("data:image/svg+xml,")
                && uri.len() <= DEVTOOLS_ICON_BYTES
                && !uri.contains(['"', '\\', '\n', '\r'])
        })
        .take(DEVTOOLS_ICONS_MAX)
        .collect()
}
